import random, copy
from scipy.sparse.linalg import eigs
from reference import Task
import numpy as np

def solve_ncv(problem, ncv):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    w,v=eigs(A,k=k,v0=np.ones(N),ncv=max(ncv,2*k+1),maxiter=N*200)
    pairs=sorted(zip(w,v.T), key=lambda p:-abs(p[0]))
    return [vec for _,vec in pairs]

task=Task();
for ncv in [11,12,13,14,15,16]:
    ok=True
    for seed in random.sample(range(10000), 100):
        prob=task.generate_problem(n=300, random_seed=seed)
        sol=solve_ncv(copy.deepcopy(prob), ncv)
        if not task.is_solution(prob, sol):
            ok=False; print('ncv', ncv, 'fail seed', seed); break
    print('ncv', ncv, 'ok', ok)
